#pragma once

#ifdef PEQ_PLAYER
#include "player.h"
#include "xfsrc.h"
#else
#include "stock.h"
#endif

/* Runtime transition record in tmpfs (zero flash wear): demo writes it right before sending {set-gapless} (and on
 * setting changes), with the effective crossfade duration for the upcoming join (0 = gapless-only / off). */
#define XFADE_FILE "/tmp/m1plus-xfade"
#define XFADE_TMP "/tmp/m1plus-xfade.tmp"
#define XFADE_MAGIC "M1XFD01" /* 8 bytes with NUL */
#define XFADE_MAX_SEC \
    12 /* the longest duration the Crossfade page offers (tools/pod_ui.py cards_xfade: its slider is 1 .. 12) */
#define XFADE_MIN_SEC 1
#define XFADE_DEF_SEC 5

typedef struct {
    char magic[8];
    int seconds; /* 0 = off / gapless-only for this transition, 1..XFADE_MAX_SEC = overlap duration */
    int seq; /* monotonic counter bumped by demo on each preload or setting update */
    int keep; /* 1: Crossfade is on and this join is between two music tracks, faded or not (same album, a short
               * track): a kept output goes on across it (patch/xfsrc.c). 0: off, or a join crossfade stays out of. */
} xfade_record;
_Static_assert(sizeof(xfade_record) == 20, "xfade record layout");

/* The kept output, for demo to show (Now Playing's info page): the player writes the rate its output stays open at
 * while it converts the tracks to it (patch/xfsrc.c), and 0 when the output is a track's own again. tmpfs. */
#define XFOUT_FILE "/tmp/m1plus-xfout"
#define XFOUT_MAGIC 0x314f4658 /* "XFO1" */
typedef struct {
    int magic;
    int rate; /* Hz, 0: not converting */
} xfout_record;

#ifdef PEQ_PLAYER

enum { XF_IDLE, XF_ACTIVE, XF_ABORT, XF_TAIL_IN, XF_DONE };

/* State carried across a gapless join when Track A hits EOF before Track B's fade-in reached 1.0 (e.g. VBR duration
 * overestimate). Track B's instance continues the fade-in smoothly from u to 1.0. */
typedef struct {
    int active; /* 1: Track B still needs to finish its fade-in */
    double u; /* progress reached in [0, 1) */
    double dur; /* total crossfade duration in seconds */
} xfade_carry;

typedef struct {
    int state; /* XF_* */
    int rate, channels, fmt, bps; /* Track A stream parameters */
    double total_s; /* Track A total duration from demuxer_get_time_length, <= 0 if unknown */
    double b_total_s; /* Track B total duration (-1 = not yet queried, 0 = unknown, >0 = seconds) */
    double last_pos; /* last decoded stream position (for backward seek detection) */
    double last_check; /* last stream position when XFADE_FILE was checked (re-checks every 0.5 s while preloaded) */
    int checked_seq; /* last xfade_record.seq inspected for the current preload */
    int bad_seq; /* xfade_record.seq whose Track B hit early EOF (prevents re-entering fade after re-preload) */
    int next_sec; /* effective crossfade seconds for the current preload (0 = skip) */
    int next_bad; /* 1: current preload was inspected and is ineligible (DSD, MQA, short, unsupported, failed init) */

    /* Active overlap state (Track B decoded from next_mpctx->sh_audio) */
    int b_rate, b_ch, b_fmt, b_bps;
    double b_rg; /* Track B ReplayGain linear scale (1.0 when RG off / unset) */
    xf_src
        *src; /* converts Track B to Track A's rate (NULL when equal); handed on whole at the join (xfade_take_src) */
    int b_eof; /* 1 once Track B's decoder reached EOF */

    /* Fade progress */
    int pos_frames; /* frames elapsed in current fade (<= 12 s * 384 kHz = 4.6M) */
    int tot_frames; /* total frames in crossfade */
    double dur_s; /* crossfade duration in seconds */
    double ga, gb; /* current Track A / Track B linear gains (used for smooth abort ramp) */
    int abort_left, abort_tot; /* 20 ms ramp frames for mid-fade abort */
    double abort_ga0, abort_gb0; /* gains when abort started */
    float hold[2]; /* last Track B sample (decays smoothly during abort without pulling more) */
} xfade_dsp;

int xfade_load(xfade_record *r); /* 1: valid record; 0: none/invalid (r zeroed) */
void xfade_reset(xfade_dsp *x, int rate, int channels, int fmt, int bps);
int xfade_carry_out(const xfade_dsp *x, xfade_carry *c); /* 1 if Track B must finish a partial fade-in */
void xfade_carry_in(xfade_dsp *x, const xfade_carry *c);
xf_src *
xfade_take_src(xfade_dsp *x); /* Track B's converter, to carry to B's own instance (NULL: none or fade abandoned) */
void xfade_release(xfade_dsp *x); /* frees what the instance still owns */
/* Runs at the top of play(): returns 1 if samples were modified in-place, 0 if left bit-exact untouched. */
int xfade_process_float(xfade_dsp *x, float *audio, unsigned frames);
int xfade_process_native(xfade_dsp *x, void *audio, unsigned frames);

#else
/* demo's side (patch/xfadeset.c): persistent settings and preload/smart-album coordination. */
#define XFADE_SET_FILE \
    "/mnt/data/m1plus/playback-crossfade" /* one character: 'a'..'l' = on, 1..12 s; 'A'..'L' = off, 1..12 s kept; missing or other = off, 5 s */
#define XFADE_SET_TMP "/mnt/data/m1plus/playback-crossfade.tmp"
#define XFADE_AUTO_FILE "/mnt/data/m1plus/playback-crossfade-auto" /* "0" always, "1"/missing smart cross-album */
#define XFADE_AUTO_TMP "/mnt/data/m1plus/playback-crossfade-auto.tmp"

int xfade_on(void); /* the Crossfade switch: 1 on, 0 off (default) */
int xfade_on_toggle(void); /* flip the switch, saved atomically; returns the new state or -1 */
int xfade_sec(
    void); /* the chosen duration, XFADE_MIN_SEC .. XFADE_MAX_SEC (default XFADE_DEF_SEC), kept while the switch is off */
int xfade_sec_set(int sec); /* save the duration atomically; returns it or -1 */
int xfade_seconds(void); /* 0 while off, else xfade_sec() */
void xfade_show(
    void *
        win); /* the Crossfade page: the duration card, Keep Albums Gapless and the note show while the switch is on; the slider and its text */
void xfade_opened(
    void *win); /* the page's slider handlers (after xfade_show: setting the slider is not a change to save) */
int xfade_auto(void); /* 1 = smart cross-album (default), 0 = always */
int xfade_auto_toggle(void); /* toggle smart cross-album; returns new state or -1 */
void xfade_boot(void); /* remove stale /tmp/m1plus-xfade and /tmp/m1plus-xfout at startup */
int xfade_out_rate(void); /* Hz the player's output is kept at while it converts the track to it (XFOUT_FILE), 0 none */
void xfade_on_preload_cancel(void); /* clear runtime state after queue edit / mode change */
int xfade_auto_change(void); /* called from rd_auto_change (Hook 36) before stock mclAutoChange */
#endif
